shape.script:

#uses "libs/kpiDataAccess"

main()
{
  // Register this shape for dpConnect push callbacks
  kpiDataAccessInit(this);

  // Load the KPI Configuration HTML via loadSnippet.
  // This injects the oaJsApi library into the page.
  // Path includes the /data/ prefix as required by loadSnippet().
  // Default page: sources. Can be overridden by panel $-parameter "startPage".
  string startPage = "sources";
  if (isDollarDefined("$startPage"))
    startPage = getDollarValue("$startPage");
  this.loadSnippet("/data/html/pi-webview/" + startPage + ".html");
}
